mapper.update:
UPDATE tb_log_policy
   SET req_now_yn  = 'N',
       last_req_dt = CURRENT_TIMESTAMP,
       next_req_dt = #{nextReqDt, jdbcType=TIMESTAMP}
 WHERE server_id = #{serverId}

UPDATE tb_log_policy
   SET last_recv_dt = CURRENT_TIMESTAMP
 WHERE server_id = #{serverId}

mapper.select:
SELECT 
  FROM tb_log_source s
 WHERE s.log_id = #{logId}

SELECT COUNT(*)
  FROM tb_log_source s
 WHERE s.server_id = #{serverId}
   AND s.log_path  = #{logPath}

   AND s.log_id <> #{excludeLogId}

SELECT COALESCE(MAX(s.sort_ord), 0)
  FROM tb_log_source s
 WHERE s.server_id = #{serverId}

SELECT n.snap_id, n.log_id, n.server_id, n.collect_dt, n.status_cd, n.line_cnt, n.byte_cnt, n.content
  FROM tb_log_snapshot n
 WHERE n.snap_id = #{snapId}

SELECT x.snap_id
  FROM (
        SELECT n.snap_id,
               ROW_NUMBER() OVER (ORDER BY n.collect_dt DESC, n.snap_id DESC) AS rn
          FROM tb_log_snapshot n
         WHERE n.log_id = #{logId}
       ) x
 WHERE x.rn > #{keep}

mapper.delete:
DELETE FROM tb_log_snapshot
 WHERE snap_id IN
#{id}
